import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    edges = []

    for i in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        edges.append((u, v))
        adj[u].append(v)
        adj[v].append(u)

    added_edges = []
    result_edges = []

    visited = [False] * (n + 1)

    for start_node in range(1, n + 1):
        if visited[start_node]:
            continue

        stack = [start_node]
        visited[start_node] = True

        while stack:
            u = stack.pop()

            current_degree = len(adj[u])

            if current_degree % 2 == 1:
                if u == start_node:
                    pass
                else:
                    added_edges.append((u, u))
                    adj[u].append(u)
                    current_degree += 1

            while len(adj[u]) > 0:
                v = adj[u].pop()

                if not visited[v]:
                    visited[v] = True
                    stack.append(v)
                else:
                    if len(adj[v]) > 0:
                        w = adj[v].pop()
                        if w == u:
                            result_edges.append((u, v))
                            result_edges.append((v, u))
                        else:
                            if len(adj[w]) > 0:
                                z = adj[w].pop()
                                if z == v:
                                    result_edges.append((u, v))
                                    result_edges.append((w, z))
                                else:
                                    if len(adj[z]) > 0:
                                        y = adj[z].pop()
                                        if y == w:
                                            result_edges.append((u, v))
                                            result_edges.append((z, y))
                                        else:
                                            result_edges.append((u, v))
                                            result_edges.extend([(w, z), (z, y), (y, w)])
                                    else:
                                        result_edges.append((u, v))
                                        result_edges.append((w, z))
                                        result_edges.append((z, w))
                            else:
                                result_edges.append((u, v))
                                result_edges.append((v, u))
                    else:
                        result_edges.append((u, v))
                        result_edges.append((v, u))
                else:
                    result_edges.append((u, v))
                    result_edges.append((v, u))

    total_edges = len(result_edges) + len(added_edges)
    print(total_edges)

    for u, v in result_edges:
        print(f"{u} {v}")

    for u, v in added_edges:
        print(f"{u} {v}")

solve()
